// Storage-agnostic contract for auth. Implementations: ./repositories/mongo.ts, ./repositories/drizzle/
// All ids are strings (UUIDs generated by the service; token/code ids are SHA-256 hex hashes).
// Expiry is always re-checked by the service, so implementations may purge lazily.

export interface User {
  id: string;
  username: string;
  passwordHash: string;
  createdAt: Date;
}

export interface WebAuthnCredential {
  id: string;
  userId: string;
  credId: string; // base64url
  publicKeyPem: string;
  counter: number;
  transports?: string[];
  name: string;
  createdAt: Date;
  lastUsedAt?: Date;
}

export interface WebAuthnChallenge {
  id: string;
  type: "register" | "login";
  challenge: string; // base64url
  userId?: string;
  authRequestId?: string;
  expiresAt: Date;
}

export interface AuthRequest {
  id: string;
  clientId: string;
  redirectUri: string;
  state?: string;
  scope: string;
  codeChallenge: string;
  expiresAt: Date;
}

export interface AuthCode {
  id: string; // sha256(code)
  userId: string;
  clientId: string;
  redirectUri: string;
  scope: string;
  codeChallenge: string;
  familyId: string; // tokens issued from this code share it (replay => revoke)
  used: boolean;
  expiresAt: Date;
}

export interface AccessToken {
  id: string; // sha256(token)
  userId: string;
  clientId: string;
  scope: string;
  familyId: string;
  expiresAt: Date;
}

export interface RefreshToken extends AccessToken {
  revoked: boolean;
}

/** Thrown by `create` methods when a unique constraint is violated. */
export class DuplicateKeyError extends Error {
  constructor(message = "Duplicate key") {
    super(message);
  }
}

export interface UserRepository {
  /** @throws DuplicateKeyError when the username exists */
  create(user: User): Promise<void>;
  findById(id: string): Promise<User | null>;
  findByUsername(username: string): Promise<User | null>;
  updatePasswordHash(id: string, passwordHash: string): Promise<void>;
}

export interface CredentialRepository {
  /** @throws DuplicateKeyError when credId exists */
  create(cred: WebAuthnCredential): Promise<void>;
  findByCredId(credId: string): Promise<WebAuthnCredential | null>;
  listByUser(userId: string): Promise<WebAuthnCredential[]>;
  recordUse(id: string, counter: number, usedAt: Date): Promise<void>;
  /** @returns false when nothing matched */
  delete(userId: string, id: string): Promise<boolean>;
}

export interface ChallengeRepository {
  create(challenge: WebAuthnChallenge): Promise<void>;
  /** Atomically delete and return (single use). */
  consume(id: string, type: WebAuthnChallenge["type"]): Promise<WebAuthnChallenge | null>;
}

export interface AuthRequestRepository {
  create(req: AuthRequest): Promise<void>;
  findActive(id: string, now: Date): Promise<AuthRequest | null>;
  /** Atomically delete and return if not expired. */
  consumeActive(id: string, now: Date): Promise<AuthRequest | null>;
}

export interface AuthCodeRepository {
  create(code: AuthCode): Promise<void>;
  /** Atomically flip used=false -> true and return the code; null if missing or already used. */
  redeem(id: string): Promise<AuthCode | null>;
  find(id: string): Promise<AuthCode | null>;
}

export interface TokenRepository {
  /** Persist an access/refresh pair (atomically where the backend supports it). */
  createPair(access: AccessToken, refresh: RefreshToken): Promise<void>;
  findActiveAccess(id: string, now: Date): Promise<AccessToken | null>;
  findAccess(id: string): Promise<AccessToken | null>;
  findRefresh(id: string): Promise<RefreshToken | null>;
  /** Atomically flip revoked=false -> true and return the token; null if missing or already revoked. */
  rotateRefresh(id: string): Promise<RefreshToken | null>;
  /** Revoke every refresh token and delete every access token in the family. */
  revokeFamily(familyId: string): Promise<void>;
}

export interface AuthRepository {
  readonly users: UserRepository;
  readonly credentials: CredentialRepository;
  readonly challenges: ChallengeRepository;
  readonly authRequests: AuthRequestRepository;
  readonly authCodes: AuthCodeRepository;
  readonly tokens: TokenRepository;

  /** Create indexes / run migrations. */
  init(): Promise<void>;
  /** Remove expired rows (no-op where the database has native TTL). */
  purgeExpired(now: Date): Promise<void>;
  close(): Promise<void>;
}
